INSERT INTO `jou_info` VALUES (1, '透平试验件对试验台横振不平衡响应的影响', '刘应,石䶮,狄广强,梁尔访,李正美,刘长利,周心洁', '摘要:重型燃气轮机透平试验台系统由试验台和试验件两部分构成。对于已经建成的试验台，需要考虑不同试验件对试验台横振不平衡响应的影响。本文利用机械阻抗综合法的阻抗匹配原理，将未知试验件的动力学特性模化为交界面上的机械阻抗，来确定试验件对试验台横振不平衡响应的影响，得出未知试验件的设计限制范围。同时，建立了某个试验件和试验台的动力学模型，分析了该系统的横向振动不平衡响应，验证了试验件不平衡响应的设计限制范围的有效性。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20231019002?viewType=HTML');
INSERT INTO `jou_info` VALUES (2, '基于交互式进化算法的三维表情动画生成', '张雯婷,刘漫丹,朱宝旭,谢立志', '摘要:三维面部表情动画已广泛融入人们的日常生活，但目前大多数表情生成技术并未考虑到实际用户的偏好。这些方法大多依赖于预先定义的心理原型，限制了其生成丰富且具有表现力的表情动画的潜力。针对这两个问题，本文提出了一种全新的表情动画编码方案，并采用交互式遗传算法(InteractiveGeneticAlgorithm,IGA)实现表情动画的自动进化，解码时则采用Dirichlet自由变形算法(DirichletFree-FormDeformation,DFFD)控制人脸网格发生形变。此外，为了维持表情动画种群的多样性，提出了两种变异算子：带屏闭区间的均匀变异和共享变异点的均匀变异。实验结果证实，这两种算子有效降低了进化过程中种群内的相似度。实际用户参与的实验进一步验证了所提方法在生成符合用户偏好且丰富多样的表情动画方面的可行性。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240831001?viewType=HTML');
INSERT INTO `jou_info` VALUES (3, '多齿氨基酚氧基锌络合物催化外消旋β-丁内酯开环聚合研究', '王真,马海燕', '摘要:聚-3-羟基丁酸（P3HB）的立体规整性对其物理机械性能有很大影响，设计合成高效催化剂实现外消旋β-丁内酯立体选择性开环聚合成为该领域的难点和热点问题。本文合成了一系列具悬垂苯并咪唑结构的氨基酚氧基锌络合物Zn1-Zn7，其中Zn4和Zn7为首次报道，Zn4的分子结构进一步经X-ray单晶衍射表征。在异丙醇存在下，该系列锌络合物对外消旋β-丁内酯开环聚合具有较好的催化活性，TOF值最高达116h−1，并具有一定的间规立体选择性（Pr=0.58~0.66）。配体各取代基尤其是酚氧基邻位取代基对络合物催化活性影响显著，但对立体选择性的影响不明显。基于活性中心结构、聚合物端基分析结果，推测该系列络合物通过配位-插入机理催化外消旋β-丁内酯聚合得到异丙氧基和羟基封端的线性P3HB。此外，在不影响立体规整度判断的情况下，开发了一种利用核磁氢谱评价P3HB规整度的方式，更为便捷、经济。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240807002?viewType=HTML');
INSERT INTO `jou_info` VALUES (4, '一类存在恶意观点的社会网络舆论演化与防御问题研究', '丁文杰,杨文', '摘要:针对社会网络中的一类舆论安全问题，提出包含嫌疑人、防御者和普通个体的社会网络观点演化模型，将嫌疑人和防御者建模为带外源输入的网络节点，嫌疑人向其它个体传播恶意观点，防御者向其它个体传播积极观点，通过计算群体期望观点到恶意观点和积极观点的距离来判断公共舆论是否安全，并据此确定了维护公共舆论安全的积极观点应满足的参数条件，又进一步分析社会群体期望观点收敛的充分条件、设计低成本的有效积极观点的计算方法。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240823004?viewType=HTML');
INSERT INTO `jou_info` VALUES (5, '基于高阶空间交互作用的姿态估计网络', '黄晓宇,陈佳艺,吴艺玮,吴胜昔,王学武', '摘要:人体姿态估计是计算机视觉领域的一个重要研究方向。尽管随着深度学习技术的进步，现有的姿态估计模型在预测人体关键点方面已经取得了显著成效。然而，在处理复杂场景如严重遮挡、复杂背景、极端姿态、多尺度变化和光照变化时，这些模型仍然面临挑战，准确度往往受到影响。为解决这一问题，本文提出了一种改进的基于HRNet的人体姿态估计方法，该方法通过引入高阶空间交互和注意力机制，显著提升了模型在复杂场景中的表现。采用递归门控卷积和卷积注意力模块以增强模型在高阶空间特征提取的能力。实验结果表明，提出的方法在COCO2017数据集上超越了现有主流方法，实现了更高的姿态估计精度。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240731001?viewType=HTML');
INSERT INTO `jou_info` VALUES (6, '基于多层级领域自适应网络和置信度约束的道路场景语义分割方法', '万才路,堵威', '摘要:语义分割旨在为图像中的每个像素分配一个类别标签，具有广泛的应用，比如自动驾驶。在实际应用中，一个在某一场景训练的语义分割模型无法有效地应用到其他场景，这成为其实际应用中的一个关键问题。像素级域内自适应方法已被证明是一种解决这个问题的有效方法。然而，这种方法不能有效地利用空间位置信息，并且容易受到噪声伪标签的影响。为了解决这些问题，首先提出了一个多层级领域自适应网络和一个置信度约束的方法。然后利用空间先验知识提出了一种阈值方法，以提高在域内自适应中使用的伪标签的质量。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240731003?viewType=HTML');
INSERT INTO `jou_info` VALUES (7, '基于GAB模型预测包装后卷烟烟丝水活度和含水率的方法', '薛诗凡,凌荣鑫,张玮,华青,谢雯燕,吴达,陈勇,楼佳颖', '摘要:开发了一种预测包装后烟丝水活度和含水率的新方法。首先绘制原辅材料的等温吸湿曲线，GAB模型进行拟合，建立相应的等温吸湿曲线方程。然后基于水分总量恒定和平衡后各组分水活度一致的原理，建立烟丝与包装辅材间水分迁移的预测模型，该模型能够成功预测烟丝在包装后的水活度和含水率。结果表明，在水活度0.2~0.8的范围内，GAB模型能够有效模拟4种不同盒型卷烟的烟丝、滤棒和烟盒的等温吸湿曲线，拟合后的R2值均大于0.99，且预测的包装后烟丝水活度和含水率的相对偏差均小于5%。因此本方法在预测包装后烟丝水活度和含水率方面具有较高的准确性，为卷烟烟丝和包装材料的水分设计提供了指导，同时为减少烟丝水分向包装材料的迁移、稳定保持卷烟水分提供了理论依据和方法支持。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240910001?viewType=HTML');
INSERT INTO `jou_info` VALUES (8, '云边场景下基于合作博弈的数据上传优化', '钟传江,虞慧群,范贵生', '摘要:在现有基于边缘计算的移动群智感知场景很少有考虑边缘服务器之间的协作。而多边缘服务器协作面临边缘服务缓存、边缘设备资源约束和大规模边缘用户任务卸载的挑战。针对以上挑战，提出了一种面向多边缘服务器合作博弈和离散粒子群（MCG+DPSO）优化的计算卸载算法。该算法首先通过多边缘服务器之间的合作博弈（MCG）得到边缘用户任务在边缘服务器之间的中继初始方案。然后，将得到的初始方案作为离散粒子群算法（DPSO）的初始解。最后，通过DPSO算法得到最优解，实现用户任务和边缘服务器的匹配，从而最大化的降低移动感知平台数据上传的服务延迟和服务成本。通过在真实数据集上进行大量对比实验，实验结果表明与云策略、边缘间不通讯策略、随机策略、合作博弈策略、DPSO算法和差分进化算法相比，MCG+DPSO算法最多可以再降低3.2%~56.0%的服务成本和3.6%~24.5%的服务延迟。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240514002?viewType=HTML');
INSERT INTO `jou_info` VALUES (9, '基于数据驱动与深度神经网络的智能配电网拓扑辨识', '杜文凯,陈心怡,薛栋', '摘要:网架结构的拓扑辨识是配电系统优化与控制的基础。随着风能和太阳能等可再生能源发电的高比例接入，配电网的拓扑结构变得更加复杂并且变化频繁，显著增加了拓扑辨识的难度。为了提高拓扑辨识的准确率，本文结合配电网的结构和运行特点，提出了一种基于自组织映射(SOM)和卷积神经网络(CNN)深度学习框架的配电网拓扑辨识方法。考虑到配电网数据的高维特性，该方法首先利用主成分分析(PCA)对高维电压幅值和有功功率数据进行降维，进而使用SOM提取数据特征，将其转换为二维特征图，并通过CNN学习输入特征与拓扑标签之间的映射关系，从而实现配电网拓扑结构的精准辨识。通过在33、69和123节点配电网算例上进行仿真实验，验证了所提方法的有效性，并且相较于其他方法，该方法在辨识准确率和鲁棒性等性能上具有明显优势。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240712001?viewType=HTML');
INSERT INTO `jou_info` VALUES (10, '表面粗糙度对WS2/Pt肖特基结光响应性能的影响', '殷泽宇,牟海川,王瑞斌,刘杰', '摘要:通过不同时长紫外臭氧处理对化学气相沉积法生长、Pt纳米颗粒(PtNanoparticles，PtNPs)修饰的多层WS2的表面粗糙度进行了0-4min不同时长的调控。当处理时长在2min时，WS2的表面粗糙度(Sa)达到最大值，约为14nm，这种现象主要归因于紫外臭氧对WS2表面的氧化形成了非晶态的WOx。随着处理时长进一步延长，多层WS2的下层新鲜WS2暴露出来，上述氧化效应得到缓解。经过测试，2min紫外臭氧处理后的WS2/Pt肖特基结，在400~900nm范围内展现出优异的光响应性能，特别是在近红外波段750nm处，其响应度高达18A/W，这相比未处理的WS2/Pt肖特基结提高了约60%。这种性能的改善主要归因于紫外臭氧处理所导致的WS2/Pt肖特基结中WS2表面粗糙化，粗糙度的增加不仅增强了由于光激发而产生的电子-空穴对的分离，而且还加强了从Pt到WS2的热电子注入。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240807001?viewType=HTML');
INSERT INTO `jou_info` VALUES (11, '一种标签融合驱动的中文医疗实体关系抽取方法', '陈闯,张维彦,阮彤,郑红', '摘要:医疗实体关系抽取是推动医疗信息化建设的关键步骤，旨在从医疗文本中抽取结构化的三元组信息。针对现有方法对实体类型标签和关系标签利用不充分的问题，提出了一种标签融合驱动的中文医疗实体关系抽取框架。首先将实体关系抽取任务拆分成双向四个命名实体识别任务，并将每个任务的标签替换为头尾实体类型标签和关系标签的融合；其次设计了三元组构造策略以最大限度利用双向抽取出的三元组；最后，利用三元组双向过滤模型筛选候选三元组。实验结果表明，该方法相较于GPLinker在F1指标上提升了3.01%。此外，该方法在医疗领域的重叠关系、多三元组和跨句三元组复杂场景中也表现出了优秀的性能。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240426002?viewType=HTML');
INSERT INTO `jou_info` VALUES (12, '基于改进U-Net3+的相控阵超声图像语义分割', '毛鑫玥,王慧锋,周家乐,顾震,颜秉勇', '摘要:超声相控阵成像已广泛应用于聚乙烯燃气管道的焊接缺陷检测中，随着机器视觉技术的快速发展，利用机器辅助或自动化分析超声图像，能极大地提高缺陷检测速度，减少人为判断失误的情况发生。在基于超声图像的焊接缺陷检测技术中，图像语义分割精度对缺陷类别和严重等级的判定至关重要。本文在U-Net3+网络的基础上提出一种融入残差及注意力机制的改进模型，并应用于电熔焊接缺陷检测的相控阵超声图像语义分割。首先，改进模型通过在编码器各层之间采用残差结构来提升编码器的图像特征提取能力，其次通过在跳跃连接中引入卷积块注意力模块(ConvolutionalBlockAttentionModule,CBAM)，加强模型对原始图像信息的利用率，使模型更易聚焦于原始图像中的有效区域。最后通过实验结果表明，改进后的模型在电熔焊接超声图像上具有良好的分割效果，在Dice、mIoU两项指标上，相比U-Net分别提升了8.81%和12.84%；相比U-Net3+的分割效果分别提升了1.09%和1.81%。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240305003?viewType=HTML');
INSERT INTO `jou_info` VALUES (13, '纳米颗粒与表面活性剂协同稳定C/W乳液及其耐盐性', '李露露,许彪,刘涛', '摘要:使用椰油酰胺丙基甜菜碱（CAPB）与纳米二氧化硅（SiO2）颗粒协同稳定高内相CO2/水（C/W）乳液。实验测定了乳液的半衰期、表观黏度和界面张力，考察了纳米颗粒浓度、盐离子种类以及矿化度对所稳定乳液稳定性的影响，并将该乳液应用于驱替模拟油的实验。结果表明，4.00%（质量分数）的CAPB单独稳定乳液的半衰期为4.60h，驱替效率为70.33%；0.70%的纳米SiO2颗粒与4.00%的CAPB协同稳定乳液的半衰期为21.92h，驱替效率为77.61%；在Na+质量分数为7.00%时，前者可稳定4.04h，后者可稳定15.24h；在Ca2+质量分数为0.05%时，前者可稳定4.37h，后者可稳定13.20h；在矿化度为1×104mg/L时，后者能够稳定17.88h，驱替效率达55.98%。CAPB主要作用于乳液的形成，SiO2则主要作用于提高乳液的稳定性，SiO2/CAPB协同稳定的乳液体系能够提高模拟油驱替的采收率。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240520001?viewType=HTML');
INSERT INTO `jou_info` VALUES (14, '生物基聚碳酸酯的合成及其光学特性调控', '周乾,陆韬,刘梦娟,方炜,吴国章', '摘要:生物基聚碳酸酯（PIC）受到分子链内刚性脂环骨架和醚键的限制，导致其折射率低、双折射值和吸水率偏高。本文以碳酸二苯酯（DPC）、9,9-二(4-(2-羟乙氧基)苯基芴（BPEF）和异山梨醇（ISB）为原料，通过熔融酯交换法合成了高分子量、无规分布的生物基共聚碳酸酯（PFIC）。Cardo结构单体BPEF的引入，赋予了PFIC比PIC更优异的光学、力学、热稳定性和疏水性，为拓宽生物基聚碳酸酯在光学薄膜领域的应用提供了支撑。当BPEF摩尔分数为22%~70%时，PFIC薄膜呈现负色散特性，固定BPEF摩尔分数为65%时，该PFIC薄膜具有高折射率（nd=1.620）和低双折射效应（Δn=0.00007）。此外，PFIC的分子链取向度及其双折射值随着薄膜拉伸温度降低、拉伸比和拉伸速率提高而增加，但并不影响其双折射波长色散性。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240527002?viewType=HTML');
INSERT INTO `jou_info` VALUES (15, '热原子系统中非耗散反PT对称奇异点的观测', '黄铖楠,钮月萍,龚尚庆,张示城', '摘要:非厄米系统在奇异点（Exceptionalpoints,EPs）附近对非厄米参量有着极高的灵敏度，这使得基于EP的精密传感在诸多领域得到应用。然而，传统的宇称时间反演（Parity-time,PT）对称系统需要引入增益和损耗，这会引起量子噪声问题。反PT对称系统可以在不引入线性增益和损耗的同时保持高灵敏度特性，但是热原子非耗散反PT对称系统中EP的实验观测仍是一个难点。本文通过热原子系统的远失谐四波混频效应证明了非耗散反PT对称性，并实验观察到EP，有望为室温条件下的量子传感和量子信息处理等应用提供一种可行的方案。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240513002?viewType=HTML');
INSERT INTO `jou_info` VALUES (16, '基于多元线性回归和反向传播人工神经网络预测离子液体的声速', '季常征,万仁,时兆翀,彭昌军,刘洪来', '摘要:离子液体的声速可采用包括实验测定，半经验模型和理论研究方法获得。其中，定量结构-性质关系(QSPR)模型已受到广泛关注。但构造一个有效的QSPR模型取决于选择合适的分子描述符。本文采用片段活度系数类导体屏蔽模型(COSMO-SAC)获得的离子液体电荷密度分布片段面积(Sσ)和空穴体积(VCOSMO)两个描述符，采用多元线性回归(MLR)和反向传播人工神经网络(BP-ANN)分别构建了u-MLR和u-ANN两个用于描述离子液体声速(u)的QSPR模型。模型中包含了温度和离子液体相对分子量。所涉及的数据集包括171种离子液体的5114个数据点。在总的数据集中，u-MLR和u-ANN的决定系数R2分别为0.9706和0.9995。计算的绝对平均相对误差AARD分别为1.59%和0.10%，均方根误差RMSE分别为30.68和4.12。证明基于人工神经网络建立的u-ANN模型的预测效果明显优于基于线性回归方法建立的u-MLR模型的预测效果。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240417001?viewType=HTML');
INSERT INTO `jou_info` VALUES (17, '基于ACT-R的认知间隔重复学习方法', '吴蕴超,罗飞,陶俊臣,王晨,张子亿', '摘要:间隔重复学习方法在辅助学生自主学习方面发挥了重要的作用；然而传统的间隔重复算法在间隔控制上过于僵化，导致学生每日的学习任务量差异明显，进而影响学习效率。为了提升自主学习效率，提出了一种基于ACT-R（adaptivecontrolofthought-rational）的认知间隔重复学习方法。一方面，基于ACT-R规划学习过程，模拟学生学习行为并提取主导模型记忆变化的激活参数；另一方面，提出了遗忘曲线切割算法，将遗忘特性反映到学习规划之中，并提取记忆留存率与推荐复习间隔等参数；最后，基于二者所得学习参数，针对特定的学习任务动态地生成间隔重复学习规划。实验分析表明，相较于传统的间隔重复学习算法，基于ACT-R的认知间隔重复学习方法可以合理并有效地安排自主学习任务，每日学习任务量更加均衡，每个任务的学习时间分布也更加合理。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240617001?viewType=HTML');
INSERT INTO `jou_info` VALUES (18, '基于AFP靶点的肝细胞癌的免疫治疗研究', '张洁,汤丁越,王成烨,高雅文,徐文青,刘思雅,肖啸,吴侠', '摘要:AFP会在大约70%~80%的肝细胞癌患者中表达，可作为肝细胞癌免疫治疗的靶点。但目前大多以AFP为靶点的肿瘤疫苗的临床实验效果欠佳，因此急需开发一种更有效的、基于AFP抗原的治疗性肿瘤疫苗。以复制缺陷型腺病毒为载体，构建了一种肝癌治疗性病毒载体Ad-hAFPm。该载体通过表达AFP/HSP70融合蛋白和GM-CSF来实现AFP抗原的特异性靶向治疗。在两种过表达人AFP的细胞系皮下移植瘤模型中模拟验证了Ad-hAFPm病毒载体的治疗效果。结果表明，Ad-hAFPm病毒在两种皮下移植瘤模型中均表现出良好的肿瘤抑制效果，肿瘤内免疫细胞浸润水平显著升高，并呈现出一定的靶向性优势，为肝细胞癌治疗性疫苗的研究奠定了实验基础。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240601001?viewType=HTML');
INSERT INTO `jou_info` VALUES (19, '基于膨胀因果卷积和注意力机制的气体识别方法', '俞凌伟,杨孟平,杨海,王喆', '摘要:提出了一种基于膨胀因果卷积和注意力机制的气体识别方法，该算法结合Transformer中的注意力机制和多尺度时态卷积网络，分别提取全局和局部特征，提取更具表示性的特征并获得更大的感受野，捕获气体的瞬时信息和变化趋势。在两个不同数据集上进行了实验，结果表明，所提出的方法分别达到99.47%和99.61%的准确率，优于现有主流方法，证实了其有效性。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240614001?viewType=HTML');
INSERT INTO `jou_info` VALUES (20, '葡萄糖酸钠流加工艺促进红球菌腈水合酶发酵表达', '张国辉,刘禹轩,刘燕枝,谢嘉怡,栗波,张思楠,王泽建,吴诗勇', '摘要:本研究首先考察了不同浓度的葡萄糖和氯化钴对腈水合酶（NHase）合成的影响，结果表明当葡萄糖浓度为20g/L、氯化钴浓度为0.05g/L时，NHase的表达水平得到了显著的提升；其次建立了基于发酵过程尾气质谱仪的过程生理代谢参数采集与分析系统，通过多参数相关性分析剖析了pH是影响红球菌NHase表达的关键因素，从而提出了发酵过程中流加葡萄糖酸钠控制pH的策略。与原来分批发酵工艺相比，优化后的工艺在菌体浓度相同的情况下，总酶活提高了93.71%，比酶活提高了97.28%，糖转化率提高了71.36%。本研究结果为工业生产中提高NHase产量提供了理论指导。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240320001?viewType=HTML');
INSERT INTO `jou_info` VALUES (21, '多种群混合进化算法求解带工序跳跃的分布式异构批量流混合流水车间调度问题', '陈三燕,王学武,王烨,顾幸生', '摘要:针对以最小化最大完工时间、总流经时间、机器等待时间以及总加权提前时间和延迟时间为优化目标的带工序跳跃的分布式异构批量流混合流水车间调度问题，提出了一种多种群混合进化算法(Multiple-populationHybridEvolutionaryAlgorithm，MPHEA)。首先，给出每个优化目标的计算方式，并制定合适的编码方案。其次，设计了总种群与四个子种群之间的并行协同进化策略。在对总种群执行混合交叉算子和变异操作后，依据快速非支配排序和拥挤距离更新种群，从而确保总种群的多样性和优质解的保留。同时，从总种群中提取出部分解，形成了4个子种群，每个子种群专注于优化一个特定的目标。总种群与子种群并行进化的方式使得子种群在各自的方向上进化时能够避免过分偏重于某一个目标，从而实现多个目标的均衡优化。考虑到工序跳跃的操作对调度问的影响，采用了相应的工序跳跃启发式规则。最后，通过仿真实验验证了MPHEA解决该调度问题的有效性和优越性。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240411001?viewType=HTML');
INSERT INTO `jou_info` VALUES (22, '滑梁式空气箔片轴承力学分析及疲劳寿命计算方法', '顾晨昀,吴洋,韩怡萱,冯伟军,安琦', '摘要:以滑梁式空气箔片轴承为研究对象，采用有限单元法建立了平箔片与底箔片滑梁连接部分的力学模型，并基于虚功原理对滑梁结构进行了力学分析，建立了箔片形变的计算模型；采用有限差分法求解了等温雷诺方程，与箔片形变的计算模型结合构建了流固耦合的计算模型，实现了对轴承的气膜压力分布的计算等。在此基础上，建立了对滑梁的最大应力进行计算的方法，并基于线性疲劳损伤理论实现了对滑梁及轴承的疲劳寿命的计算，构建了新型滑梁式空气箔片轴承的疲劳寿命计算方法。结合具体的算例，对轴承的疲劳寿命进行数值计算研究，研究表明，滑梁最大应力约为106MPa，滑梁式箔片轴承的疲劳寿命随着箔片厚度、滑梁斜率、轴承间隙及滑梁行数的增大而增大，随着滑梁列数的增大而减小，当轴承间隙为97um时，轴承寿命约为9年。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240414001?viewType=HTML');
INSERT INTO `jou_info` VALUES (23, '高软化点沥青的制备及其在锂电池中的应用', '李志硕,马成,王际童,张永正,凌立成', '摘要:本文以乙烯渣油为原料，利用空气氧化法制备出高软化点沥青，并探索了其用作锂离子电池石墨负极的包覆材料的实用性。结合元素分析、飞行时间质谱、气质联用仪、红外光谱、核磁共振氢谱和热重分析等分析表征手段，详细研究了反应过程和产物的结构特征，并初步探索了所制沥青用作锂离子电池包覆材料时对石墨负极的电化学性能的影响。结果表明，300℃时氧化交联反应开始发生；反应温度为330℃时，延长反应时间可以提高沥青的软化点、碳含量、残炭率以及芳香度，结构为多种复杂的稠环芳烃化合物；反应时间为9.5hr时所制备沥青的含碳量为93.16wt%，软化点为216.9℃，残炭率为51.4wt%，以其作为锂离子电池负极的包覆材料效果最佳，所得包覆石墨负极在100mAg−1电流密度下循环100次后，同比未包覆的材料其放电比容量提升26.3%，且循环稳定性大幅提升。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240306004?viewType=HTML');
INSERT INTO `jou_info` VALUES (24, '脱油沥青进料的气化炉火管废锅中动态灰分沉积与传热特性的数值模拟', '姚惟譞,韩洋,代正华,许建良,梁钦锋,王辅臣', '摘要:为探究脱油沥青气化工艺中的火管式废热锅炉存在的结垢问题，本文采用CFD方法，针对脱油沥青特殊的灰分组成和进出口温差较大的场景，结合熔融液相比例模型、临界速度模型与脱落模型，将整根火管划分为A~G7个管段，模拟了工业火管锅炉单根火管中的灰分沉积分布、沉积表面温度和出口温度的变化，并探究了合成气入口流量的相关影响。结果表明，火管废锅中的灰分沉积主要集中在A、B管段，在A、B段连接处出现最大沉积厚度6.37mm。灰分沉积后总传热效率仅降低0.88%，但各管段传热效率变化显著。考察合成气流量的影响时，发现合成气出口温度与合成气流量正相关。将流量由80%增加到120%，火管末端G段出口出口温度仅由590.51K增加到605.56K，结果表明可采取增加合成气流量方式提高蒸汽产量。但随合成气流量增加，除A段管壁温度降低，B～G段管壁温度均随之升高。在120%的合成气流量下，温度最高的B、C段管壁温度分别为756K和768K，接近材质最高工作温度773K，影响到锅炉运行的稳定性。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240313001?viewType=HTML');
INSERT INTO `jou_info` VALUES (25, '平衡信息与动态更新的原型表示联邦学习', '徐炜钦,肖婷,王喆', '摘要:联邦学习（FL）是一种分布式机器学习方法，旨在通过训练模型而不共享客户之间的原始数据来解决隐私问题。然而，跨客户端数据的异构性会阻碍FL中的优化收敛性和泛化性能。为了解决这个问题，本文提出了平衡信息与动态更新的联邦原型学习（BD-FedProto）框架，它由两个组件组成：原型调度的动态聚合（DA）和对比原型聚合（CPA）。前者动态地调整局部学习和全局学习之间的比例，以平衡局部知识和全局知识的有效性；后者利用缺失的类作为负样本，通过统一的原型集群来学习未知的分布。在CIFAR-10和MNIST数据集上的实验结果表明，BD-FedProto能有效提高FL的分类性能和稳定性。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20231019001?viewType=HTML');
INSERT INTO `jou_info` VALUES (26, '立方型与PC-SAFTEoS对纯组分热力学性质预测能力的评价', '孙佳惠,王潇然,赵文英,项曙光,金欣', '摘要:采用18类382种物质的沸点下饱和蒸气压、液体体积、蒸发焓的实验值评价Redlich-Kwong（RK）、Soave-Redlich-Kwong（SRK）、Peng-Robinson（PR）、扰动链统计缔合流体理论状态方程（PC-SAFT）状态方程（EoS）对热力学性质的预测能力，通过计算值和实验值的平均相对偏差，评价了4种状态方程对18类物质预测结果的准确性。结果表明，对沸点下蒸发焓、饱和蒸气压、液体体积预测结果最准确的是PC-SAFTEoS，平均相对偏差分别为1.57%、1.20%、0.99%；PR、SRKEoS对蒸发焓预测结果的平均相对偏差分别为2.57%和2.68%，对饱和蒸气压预测结果的平均相对偏差分别为1.47%和1.80%，且其对液体体积的预测结果平均相对偏差也远大于PC-SAFTEoS；RKEoS对3种热力学性质预测结果的平均相对偏差均超过18.00%。对有机物尤其是缔合物质的热力学性质的预测应该优先选择PC-SAFT状态方程。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240115001?viewType=HTML');
INSERT INTO `jou_info` VALUES (27, '基于迭代进化的肠出血性大肠杆菌噬菌体鸡尾酒的抗菌效果评价', '丁子韩,谢宇桢,曹晨昕,陈泉,刘慧,徐蓁禾,王壮,王启要,刘琴', '摘要:分离到一株抗菌能力较差的新型噬菌体vB_EcoM_CRP22，通过模拟噬菌体与细菌在自然环境中的相互作用，开发了迭代适应性进化的方法使噬菌体感染噬菌体抗性突变菌株，显著提高了噬菌体对肠出血性大肠杆菌（EHEC）的抗菌效果，由噬菌体进化株组合成的鸡尾酒制剂感染细菌后36h内能有效控制OD600低于0.4。该实验为噬菌体疗法的发展提供了新思路。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20231130002?viewType=HTML');
INSERT INTO `jou_info` VALUES (28, '基于改进注意力机制的CNN的齿轮箱故障诊断', '邵浙梁,戚知宽,周邵萍', '摘要:针对实际工况中齿轮箱振动信号复杂多变，导致传统基于卷积神经网络（ConvolutionalNeuralNetworks,CNN）的齿轮箱故障诊断方法存在诊断精度不高、训练收敛性能差等问题，首先，提出一种改进的注意力机制和一种基于注意力机制的软阈值激活函数，在此基础上，构建基于改进注意力机制的CNN故障诊断模型；然后，通过齿轮箱开源数据集的实验数据，验证改进的注意力机制和基于注意力机制的软阈值激活函数能否有效提升模型的诊断精度和训练收敛性能；最后，将构建的模型应用于实际工况齿轮箱的故障诊断。结果表明，构建的模型满足某企业齿轮箱出厂检测的需求，在诊断精度和训练收敛性等方面具有优势。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20231207002?viewType=HTML');
INSERT INTO `jou_info` VALUES (29, '聚硅氧烷/纳米二氧化钛超疏水光催化复合涂层的制备和性能', '王政华,张玲,李春忠', '摘要:采用两种不同的长链硅烷三甲氧基十六烷基硅烷(HDTMS)和三乙氧基十三氟辛基硅烷(PFTDS)对纳米二氧化钛(TiO2)进行接枝改性，分别得到改性纳米粒子HDTMS-TiO2和PFTDS-TiO2。两种改性纳米粒子分别与聚硅氧烷预聚体原位聚合，通过两步喷涂法制备了复合涂层。改性纳米粒子的分散性得以提升，在基板上形成均匀分布的粗糙结构；改性纳米粒子仅需20%（质量分数）的添加量就可使复合涂层呈现出超疏水性，并使涂层具有优异的自清洁性能、耐腐蚀性能和紫外光催化性能。本研究为设计多功能复合涂层提供了新的策略，在建筑、汽车、船舶等领域具有广阔的应用前景。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20231205001?viewType=HTML');
INSERT INTO `jou_info` VALUES (30, '阿魏酸-烟酰胺共晶的氢键作用及紫外光照稳定性', '李雨峰,井艺霏,冯海飞,王小永', '摘要:制备了阿魏酸（FA）-烟酰胺（NIC）共晶，分析了FA与NIC在共晶时及溶液中的氢键作用，并研究了FA-NIC共晶中FA的水溶性和紫外光照稳定性。红外光谱和Hirshfeld表面分析结果表明，FA-NIC共晶中FA与NIC在4处位置存在氢键作用，其强弱顺序为Ⅲ（O−H···O）>Ⅰ≈Ⅱ（O···H−N）>Ⅳ（O···H−C）。FA-NIC共晶中的FA比纯FA具有更低的紫外吸收和荧光强度，这说明FA-NIC共晶在水溶液中并没有完全解离，FA与NIC之间仍然存在氢键作用。相比纯FA，FA-NIC共晶中FA在水中的溶解度提高了88%，FA的紫外光照稳定性提高了12.7%，两者的提高归因于FA与NIC之间的氢键作用。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240116001?viewType=HTML');
INSERT INTO `jou_info` VALUES (31, '基于三氧化硫磺化的丹参酮ⅡA磺酸钠的连续化合成', '闵书樑,周长路,王超颖,万海涛,俞伟,辛忠', '摘要:利用飞秒激光微加工技术，制作了一种厘米级类卡特彼勒3D微流控芯片，并在微流控芯片内以三氧化硫为磺化剂连续制备丹参酮ⅡA磺酸钠。停留时间分布测试结果表明：微流控芯片内的整体流动状态接近于平推流。最佳磺化条件为：磺化温度25℃，n(SO3)/n(丹参酮ⅡA)=2.0，停留时间2min。与传统硫酸间歇工艺相比，丹参酮ⅡA磺酸钠产率由68.0%提升至92.3%，反应时间由120min降低至2min，E因子由27.7降低至2.1。实现了丹参酮IIA磺酸钠的绿色、安全、高效连续制备。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240123001?viewType=HTML');
INSERT INTO `jou_info` VALUES (32, '基于多目标生物地理学优化算法的模糊节能分布式流水车间调度', '张振,张丫丫,孙美玲,顾幸生', '摘要:研究了模糊节能分布式置换流水车间多目标调度问题（FuzzyEnergyEfficientDistributedPermutationFlowShopProblem，FEEDPFSP），针对最小化模糊完工时间和模糊能耗两个优化目标，提出了一种基于生物地理学的多目标优化算法（Multiple-ObjectiveBiogeography-BasedOptimization，MOBBO）。在MOBBO中，设计了一种有效的初始解生成规则，并根据两个优化目标之间的关系，设计了4种速度操作方法用于迁移过程和变异过程，并且引入快速非支配排序以及拥挤距离方法，保证每次迭代的种群质量。对比两个先进算法在480个不同规模实例下的表现，验证了所提出的MOBBO算法在解决FEEDPFSP问题的有效性。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20231225002?viewType=HTML');
INSERT INTO `jou_info` VALUES (33, '基于自上而下注意力机制的零样本目标检测', '齐鑫伟,侍洪波,宋冰,陶阳', '摘要:由于可见类和未见类目标数据分布的差异性，目前基于映射迁移策略的零样本目标检测算法在测试时容易偏向可见类别的目标，且因为不同类别在属性上的相似性，特征分布比较混乱。本文提出一种新的零样本目标检测框架，利用所设计的先验知识提取模块和自上而下注意力机制模块，为检测过程提供任务导向，引导模型在训练期间关注出现的未见类特征，提高模型对不同数据分布的判别性；还设计了一种新的对比约束以提高特征之间的聚类能力；在MSCOCO标准数据集上进行了大量实验。结果表明，该模型在标准和广义零样本目标检测任务上都取得了显著效果。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20231214001?viewType=HTML');
INSERT INTO `jou_info` VALUES (34, '基于数据库方法的离子辐照用小冲杆试验的尺寸效应研究', '陈成,赵政捷,钟继如,关凯书', '摘要:在核工业中利用小冲杆试验(SmallPunchTest，SPT)评价材料受辐照前后力学性能的变化有广阔的应用前景。围绕离子辐照，本文通过6种材料对小冲杆试样的尺寸效应进行了探讨，验证了数据库方法可用于0.1mm厚小冲杆试样获取材料强度，并对试验中存在的尺寸效应及其临界晶粒尺寸进行分析。通过数据库方法建立了厚0.1mmSPT和常规拉伸强度（屈服强度和抗拉强度）的转换方法，发现SPT获取材料屈服强度的相对误差与试样晶粒尺寸呈线性关系，其中SPT确定材料抗拉强度的最大相对误差为3.62%，屈服强度的最小误差为4.84%、最大误差为15.9%，SPT评价材料屈服强度的临界晶粒尺寸为7.4μm。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20231201002?viewType=HTML');
INSERT INTO `jou_info` VALUES (35, '基于物理信息深度学习算法的FlameD热流场重构研究', '彭浩然,胡贵华', '摘要:尽管数值模拟方法在求解流体动力学的湍流过程中发展迅速，但处理复杂的几何形状和流动过程时，在准确建模和计算速度等问题上仍面临挑战性。针对当前在计算流体力学（ComputationalFluidDynamics，CFD）上存在的计算代价大等问题，本文在传统的湍流数值模拟技术的基础上，结合机器学习，以经典的SandiaFlameD燃烧模型为例，通过引入物理信息的深度学习算法，建立物理信息神经网络架构（Physics-InformedNeuralNetwork，PINN），将符合规律的物理信息内嵌到神经网络，使得用小样本就能实现参数的流场重构。在平面维度上，分别对PINN和数据驱动方法重构的结果，与CFD软件仿真结果进行对比分析，其中PINN方法在训练集大小不及样本点总数一半的情况下，即可得到数据驱动方法在大样本情况下的重构结果，重构出燃烧过程在t=1s时刻的轴向、径向速度以及温度的L2相对误差分别为0.187213%、1.193752%，0.071325%，且在训练集占样本点总数的55%、70%、82%的情况下，PINN方法均比数据驱动方法误差小。在时间维度上，成功重构t=0.3、0.5、1s时刻的轴向速度云图，证明PINN方法能够重构出几何模型采样时间范围内任意时刻的物理场分布云图。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20231227002?viewType=HTML');
INSERT INTO `jou_info` VALUES (36, '基于振动诱导发光的Zn2+/Cd2+/Cu2+荧光化学传感器', '郭启超,王嘉琪,陈松阳,王巧纯', '摘要:在振动诱导发光单元N,N’-二苯基二氢二苯并a,c吩嗪（DPAC）N-N轴两翼的苯环上分别引入金属离子配位基团，合成了荧光化学传感器DPAC-H-COOH，其结构经核磁共振氢谱（1H-NMR）、碳谱（13C-NMR）及高分辨质谱表征，结果表明，DPAC-H-COOH通过4配位选择性结合Zn2+/Cd2+/Cu2+3种阳离子，并均以化学计量比1∶1的方式形成分子内复合物。由于离子半径的差异以及配体-金属电子转移的作用，传感器分子结合Zn2+/Cd2+/Cu2+表现出不同的荧光信号，不但可肉眼进行区分，还可以实现对上述3种性质类似的阳离子进行检测，检出限分别为80.2nmol/L、0.506μmol/L和0.263μmol/L，实现了采用单个传感器分子识别检测多种金属离子的功能。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240520002?viewType=HTML');
INSERT INTO `jou_info` VALUES (37, '颗粒尺度对CaO颗粒团簇水合反应的传质影响', '顾屹仕,沈中杰,袁鼎轩,程玉祥,王景效,吕凤,万大阳,高永川,段乐章,刘海峰', '摘要:传质是影响Ca(OH)2/CaO热化学储热体系能量存储与释放的关键因素。本文考察了3种不同粒径(100、50和25μm)的CaO颗粒团簇在水合过程中的粒径、比表面积和孔隙率等尺度效应对传质效率的影响。在水合阶段，不同粒径CaO颗粒团簇的粒径减小、比表面积增大、孔隙率降低。原先离散的CaO颗粒由于尺度效应作用更易聚集成团簇，阻碍了传质效率。与初始状态相比，随着水合转化率的提高，3种不同粒径(100、50、25μm)的CaO颗粒其团聚作用力分别降低了27.01%、32.62%和42.61%，气体有效扩散率分别下降了14.24%、12.40%和11.09%。小粒径颗粒间虽然更易聚集成团簇，但是由于小粒径颗粒具有高的气体有效扩散率，加强了反应过程中的传质效率，因此表现出更高的水合能力。基于随机孔隙模型修正量化了颗粒间团聚行为与气体有效扩散率对表观反应速率的协同影响，随着水合转化率升高，表观反应速率分别降低了78.99%、76.80%和76.20%。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240318001?viewType=HTML');
INSERT INTO `jou_info` VALUES (38, '基于同态加密支持模糊查询的高效隐私信息检索协议', '严字冬,徐贤', '摘要:隐私信息检索技术可以在进行数据检索的同时保护用户查询隐私，然而现有的隐私信息检索协议仍然不够高效，且功能较为薄弱。基于同态加密和数论原理，提出了一种高效的密文匹配机制，并在此之上设计了一个支持模糊查询的无交互对称隐私数据检索协议，从效率和功能性两个角度着手，显著提升了隐私信息检索的效率，并扩展了协议的功能。在本方案中，对上万条记录进行的单次查询仅需要秒级别的延时，在服务端延时方面优于当下最高效的关键词隐私信息检索方案，并且本方案允许进行带有通配符的模糊查询以及多关键词的查询，可以在保护用户和数据隐私的同时，获得趋近于明文查询的体验。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240228003?viewType=HTML');
INSERT INTO `jou_info` VALUES (39, '马尔可夫基因表达建模的神经网络矩闭合方法', '顾冬洋,姜庆超', '摘要:生物体的生命活动与基因表达密切相关，然而现有的基因表达矩闭合近似建模方法难以充分利用生化反应过程的潜在细节信息。本文提出了一种新颖的基于人工神经网络的矩闭合方法。该方法利用神经网络学习到矩方程组中高阶矩的低阶表示，使方程组实现闭合，并进一步结合常微分方程求解器对闭合后的方程组进行求解，最终获得精确的矩估计。实验结果表明，所提方法在预测精度和计算效率上显著优于传统方法。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240227001?viewType=HTML');
INSERT INTO `jou_info` VALUES (40, '基于GraphSAGE-MGAT的工控系统入侵检测方法', '胡育鸣,王华忠', '摘要:提出一种融合了图随机采样与聚合（GraphSAGE）和改进的图注意力网络（GAT）的工控入侵检测图神经网络算法，以处理工控入侵检测中存在的数据特征种类多和数量大等复杂特性。首先将入侵检测流量数据构建为图结构形式，利用GraphSAGE采样和聚合邻居节点信息得到节点的embedding向量，降低图结构空间复杂度，提高对大量数据处理的效率。运用改进的多头图注意力机制，丰富捕获的特征信息，计算节点之间的相关性和重要性，为各个节点分配相应权重，提高分类精准度。将该方法在工控数据集上验证，实验结果表明，该方法具有更好的时间效率以及更高的检测精度。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240507001?viewType=HTML');
INSERT INTO `jou_info` VALUES (41, '人工神经网络和响应面法优化黑曲霉发酵产淀粉酶', '王媛,王永红', '摘要:发酵过程的培养基组成及培养条件是影响黑曲霉产淀粉酶产量的关键。为提高黑曲霉F223的产酶水平，首先通过单因素实验及Plackett-Burman（PB）实验筛选出了显著影响淀粉酶酶活的成分：豆粕、玉米浆及可溶性淀粉。通过最陡爬坡实验以及中心组合实验获取回归建模数据集，以淀粉酶酶活为响应变量，分别利用传统的多项式回归以及人工神经网络回归拟合方法，建立了培养基组成与酶活之间的回归模型，得到了黑曲霉F223生产淀粉酶的培养基和培养条件的最优解。结果表明，人工神经网络结合遗传算法在数据拟合和预测能力方面优于多项式回归方法，用该算法为基础优化得到的培养基进行摇瓶发酵实验，最终淀粉酶产量达到5566.79U/mL，相比于未优化培养方案提升了92.6%。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20231209001?viewType=HTML');
INSERT INTO `jou_info` VALUES (42, '基于数值模拟的纯氧燃烧玻璃窑炉性能分析', '蒋鹏,胡贵华', '摘要:将纯氧燃烧玻璃窑炉作为研究对象，使用火焰空间与池窑双向热耦合的方法建立数值模拟耦合模型。在此基础上对窑炉性能进行研究，以提高传热效率和延长使用寿命为目的，使用正交试验方法对窑炉参数进行优化，考虑了氧化剂中氧气含量(A)、空气预热温度(B)、燃料质量流量(C)，过剩氧气系数(D)、喷嘴距玻璃液面高度(E)、烟气出口面积(F)这6个因素。结果表明，所选因素的影响程度由高到低依次为:B、E、C、A、D、F，忽略次要因素D、F的影响，选取\\textA_\\text1\\textB_\\text3\\textC_\\text3\\textE_\\text1水平为优化工况进行模拟验证，与原工况相比，碹顶相对温差降低了18.8%，传热效率提高了7.7%，有较好的优化效果。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240105001?viewType=HTML');
INSERT INTO `jou_info` VALUES (43, '基于组稀疏优化的强化学习稀疏表征', '蔡林逸,冯翔,虞慧群', '摘要:强化学习由于具有出色的数据效率和快速学习的能力，开始应用于许多实际问题以学习复杂策略。但是高维环境中的强化学习常常受限于维度灾难或者灾难性干扰，性能表现不佳甚至导致学习失败。围绕表征学习，提出了一种符合Lasso类型优化的稀疏卷积深度强化学习方法。首先，对稀疏表征的理论和优势进行综述，将稀疏卷积方法引入深度强化学习中，提出了一种新的稀疏表征方法；其次，对由稀疏卷积编码定义的可微优化层进行了数学推导并给出了优化算法，为了验证新的稀疏表征方法的有效性，将其应用于相关文献常见的基准环境中进行测试。实验结果表明，应用稀疏卷积编码的算法具有更好的性能和鲁棒性，在降低了50%以上模型开销的前提下，取得了相当甚至更优的性能。此外，还研究了稀疏程度对算法性能的影响，结果显示适当的稀疏度能获得更优的性能。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20231223001?viewType=HTML');
INSERT INTO `jou_info` VALUES (44, '超级电容器用聚苯乙烯树脂基碳微球的结构控制及其电化学性能', '王俊博,孙刚伟,张永正,沈春银,王艳莉,詹亮', '摘要:以苯乙烯和二乙烯基苯为原料，石蜡为造孔剂，采用悬浮聚合及后续热处理制得聚苯乙烯树脂基碳微球（PCS）以用作超级电容器电极材料，并对其孔结构、表面形貌及表面化学性质进行了分析。研究结果表明，当在原料体系中添加质量分数为30%的石蜡造孔剂时，所制聚苯乙烯树脂基碳微球PCS-30%的比表面积高达2589m2/g，其中微孔比表面积为2328m2/g；在Et4NBF4-PC电解液体系下，将该材料作为电极材料制备双电层超级电容器，在0.1A/g的电流密度条件下，电容器的比电容为106.4F/g，相应超级电容器的能量密度为22.1Wh/kg。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240301001?viewType=HTML');
INSERT INTO `jou_info` VALUES (45, '基于镍铝催化剂的碳酸盐加氢热解还原反应特性研究', '窦本浩,杜锦标,胡兆一,周梵,代丽娜,高云飞,王辅臣', '摘要:以白云石作为碳酸盐代表性矿物，将Ni/γ-Al2O3催化剂与白云石机械混合后，研究了H2气氛下碳酸盐催化加氢热解还原过程以及不同工况的影响。结果表明，Ni/γ-Al2O3催化剂可大幅提高碳酸盐的转化效率，气体产物中的CO与CO2的体积比由不加入催化剂时的1.105提升至加入催化剂时的2.622；过高的Ni含量、H2体积分数和过低的反应温度都会促进CH4生成反应，降低CO的选择性；催化剂可通过磁性从固体产物中分离，实验表明催化剂在多次循环反应后仍可保持活性及选择性。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20231227001?viewType=HTML');
INSERT INTO `jou_info` VALUES (46, '一种基于StyleGAN生成器的自监督人脸正面化模型', '谢立志,刘漫丹,朱宝旭,张雯婷', '摘要:提出了一种基于StyleGAN生成器的新型自监督人脸正面化模型（Self-SupervisedFaceFrontalizationModel，SFM），通过改变潜空间编码实现人脸正面化。为了合成质量优异的正面人脸图像，使用对比语言图像预训练（ContrastiveLanguageImagePretraining，CLIP）模块和自适应增强模块（AdaptiveEnhancementModule，AEM）来编辑潜空间，在最大程度上只修改面部姿态而不修改面部的其他特征。研究结果表明，本文方法无需配对人脸数据集训练就能生成质量优且完整的正面人脸图像。在定性和定量实验数据的比较中，本文方法最优。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20231221001?viewType=HTML');
INSERT INTO `jou_info` VALUES (47, 'Cu2+对水体中氧氟沙星光化学降解的影响', '周润生,徐晶,周磊,修光利', '摘要:水体中氟喹诺酮类抗生素（Fluoroquinolone，FQs）易与金属离子发生络合反应，从而影响其潜在的环境行为及生态效应。本文以典型氟喹诺酮类抗生素氧氟沙星（OFX）为例，系统探讨了二价铜离子（Cu2+）对其光化学转化降解特性的影响。综合荧光、紫外光谱分析，发现Cu2+与OFX在pH中性条件下能够形成络合比为1∶1的络合物。在365nm单波长光源的照射下，Cu2+的加入抑制了OFX光降解，荧光猝灭及激光闪光光解实验表明，该抑制作用主要是由Cu2+对OFX光致激发的静态猝灭作用导致。质谱分析结果表明，OFX直接光降解路径包括脱羧、光氧化、哌嗪环氧化裂解和去甲基化等，Cu2+存在条件下去甲基化产物未被检出。毒性分析结果表明，Cu2+的存在降低了OFX转化过程对水生生物的生态毒性。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20231229001?viewType=HTML');
INSERT INTO `jou_info` VALUES (48, '三聚甲醛-甲醛-水-[BMIM][NO3]的气液相平衡研究', '李飞,张涛,吕莉,唐文翔,唐盛伟', '摘要:研究了离子液体1-丁基-3-甲基咪唑-硝酸盐（BMIMNO3）对甲醛-水（FA-H2O）、三聚甲醛-水（TOX-H2O）体系的气液相平衡的影响。结果表明，BMIMNO3的加入可以有效改善体系的气液相平衡，加入摩尔分数为0.070的BMIMNO3可以使共沸现象消失。将非随机双液(NRTL)模型用于关联实验数据，TOX-H2O-BMIMNO3三元物系计算值与实验值的平均相对偏差为1.32%，FA-H2O-BMIMNO3三元物系计算值与实验值的平均相对偏差为1.74%。测定了TOX-FA-H2O-BMIMNO3的气液平衡数据，结果表明，BMIMNO3的加入可以使平衡时气相中的TOX摩尔分数增加17.49%。研究结果对提高气相中TOX的摩尔分数具有理论指导意义。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20231210001?viewType=HTML');
INSERT INTO `jou_info` VALUES (49, '碳/氮化钛粉体制备技术', '向茂乔,丁雯珺,朱庆山', '摘要:碳/氮化钛（TiC/N）兼具了金属和陶瓷特性，在机加工、电子和催化等领域引起了广泛关注。高质量TiC/N粉体对于制备高性能材料至关重要，但现有合成体系存在传质屏障与高反应能垒等问题，制备高质量TiC/N粉体面临较大挑战。本文系统分析了不同方法制备高质量TiC/N粉体的难点，并从强化传质和反应等方面介绍了最新进展，同时展望了TiC/N粉体的发展趋势。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240825001?viewType=HTML');
INSERT INTO `jou_info` VALUES (50, '入库车中断模式下生鲜品越库车辆调度研究', '陶柏铭,刘朝晖,潘飞', '摘要:传统的生鲜品越库车辆调度问题通常采用非中断装/卸货模式，这较易造成所卸非所需，而所需货物未能及时卸载的问题。为加快生鲜品的越库转运，降低生鲜度损耗，提出应采用允许入库车卸货过程可以中断的模式，并建立以新鲜度总衰减量最小为目标的生鲜品越库车辆调度模型。针对该模式，设计包含入库车序号、生鲜品种类、批次卸货数量的3层混合染色体编码方案，构建并采用基于批次卸货数量的自适应遗传算法求解。数值实验结果表明，入库车中断模式相较于传统的非中断模式，平均能降低13.9%的新鲜度总衰减量，且该优势会随着车辆转换时间、传送时间、批次卸/装货数量值、高衰减率生鲜品比重的降低而愈发显著。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240103002?viewType=HTML');
INSERT INTO `jou_info` VALUES (51, '基于KRAS突变肽段介导的胰腺癌免疫治疗', '贺心怡,汤丁越,张洁,丁浩,吴侠', '摘要:通过增加KRAS抗原负荷来增强机体主动免疫，开发了一种KRAS靶向的免疫治疗药物。构建了4种质粒表达载体，每种载体含有的突变肽段种类、数量、排列顺序以及连接方式不同，但均包含Q61H突变肽段，同时表达载体包装腺病毒衣壳，并在体内外进行验证及筛选。结果表明，这4种表达载体都能在体外成功表达，并在小鼠体内引起免疫反应。肿瘤药效实验表明，在含有KRASQ61H突变位点的移植瘤小鼠模型中，药物可刺激体内免疫反应从而抑制肿瘤生长，但这4种药物的药效存在明显差异，Ad-SNP1载体药效最好。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240319001?viewType=HTML');
INSERT INTO `jou_info` VALUES (52, '基于通道注意力机制增强DGNN的外骨骼机器人步态相位预测', '颜建军,许赢家,林越,金理,江金林', '摘要:利用一种基于通道注意力机制增强的有向图神经网络（ChannelAttentionEnhancedDirectedGraphNeuralNetwork,CA-DGNN）的外骨骼机器人步态相位预测方法，提高步态相位预测的准确性和可靠性。首先，研制了人体下肢姿态信息采集装置，采集了人体下肢的行走步态数据并构建人体下肢的骨架模型；之后，建立了基于CA-DGNN步态相位预测模型，提取人体步态相位的运动特征，并基于当前时刻数据预测未来时刻的步态相位；最后，探讨了滑动窗口大小对算法性能的影响。本文提高了外骨骼机器人步态相位预测的准确性和鲁棒性，为此方向研究提供了一种新的思路和方法。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240229001?viewType=HTML');
INSERT INTO `jou_info` VALUES (53, '基于局部和全局特征提取及多级特征聚合的中文方言识别模型', '孟一凡,陈宁,李泓锴', '摘要:与其他语种的方言相比，中文方言种类较多，且方言类间差异小，类内差异大，因此中文方言识别极具挑战性。考虑到中文方言间的差异性可能体现在语音的局部（短时）特性上，也可能体现在语音的全局（长时）特性上，同时还可能反映在语音的不同层级的特性上，本文提出一种融合语音局部和全局特征提取以及多级特征聚合的中文方言识别模型。首先通过Res2Block提取语音的局部特征，然后利用Conformer提取语音的全局特征，最后通过将多个Conformer级联输出进行多层级特征的聚合。跨域和非跨域的实验结果表明，该模型取得了比基线模型更高的识别准确率。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20231011003?viewType=HTML');
INSERT INTO `jou_info` VALUES (54, '考虑平箔综合弹性变形的空气箔片轴承性能', '邵聪鹏,许浩杰,李双敏,安琦', '摘要:目前关于空气箔片轴承研究中的平箔采用梁模型简化，忽略了平箔变形在轴向上具有的耦合关系导致计算精度受限的问题，建立了一种基于薄板弯曲理论、考虑平箔综合弹性变形空气箔片轴承力学模型，实现了对箔片变形与受力精确计算。结合Reynolds方程，构建了能够对空气箔片轴承力学性能与润滑性能进行计算的流固耦合算法。给定载荷0.6N、以600r/min为梯度进行试验，对比了偏心率和摩擦力矩的试验值与理论值，验证了所建立计算模型的可靠性。结合算例参数探讨了转速、载荷对轴承性能参数的影响，同时研究了平箔和波箔厚度、波拱高度、波拱半弦长等轴承结构参数对空气箔片轴承性能的影响。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240317001?viewType=HTML');
INSERT INTO `jou_info` VALUES (55, '延长盐单胞菌生产依克多因高密度发酵工艺优化', '张悦,刘昊,刘玮,余君雄,肖扬,郇晶伟,颜诚旭,庄英萍,王泽建', '摘要:建立了延长盐单胞菌（HalomonaselongataDSM2581T）高效合成依克多因的高密度发酵工艺。通过单因素实验、Plackett-Burman实验与CentralCompositeDesign系统考察了合成培养基营养组分对H.elongataDSM2581T发酵代谢的影响。优化结果表明：3.00g/L柠檬酸钠，3.00g/L氯化铵，80.00g/L氯化钠的培养基组分能够显著促进H.elongataDSM2581T菌体的生长和产物合成。根据H.elongataDSM2581T在5L发酵罐中优化后的培养基条件下的生长代谢情况，建立了葡萄糖连续流加和pH反馈控制（氨水）的补料方式进行H.elongataDSM2581T高密度发酵工艺，实施了将对数生长期发酵液中NaCl浓度从80g/L提高到130g/L的快速盐梯度冲击策略，发酵13h后OD600最高达到169.3，依克多因产量和合成速率分别达到20.0g/L和1.54g/(L·h)。这项研究为实现依克多因的低成本、高效率工业化生产提供了理论指导。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240121001?viewType=HTML');
INSERT INTO `jou_info` VALUES (56, '不同单克隆抗体聚集与断裂行为的多维分析', '陆治锦,文玺凯,刘鲁杰,王宜冰,沈春雷,伍维,沈智勇,赵黎明', '摘要:采用尺寸排阻色谱法和分析型超速离心法对ZG154和ZG187抗体的分子大小变异体进行正交分析，系统解析了造成聚集和断裂的因素。结果表明，40℃时ZG154样品在天冬酰胺329位点发生脱酰胺修饰的比例增加了30.7%，通过增加分子间相互作用，相关修饰加速了聚集，并导致断裂的发生。40℃时ZG187样品在蛋氨酸430位点发生氧化修饰的比例增加了36.9%，相关修饰降低了蛋白的稳定性，导致了断裂的发生。研究结果为上述药物研发和生产过程中的聚集与断裂问题提供了检测和分析方法。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240226004?viewType=HTML');
INSERT INTO `jou_info` VALUES (57, 'ZnCr2O4(111)-OV表面活性氢的产生及其在CO加氢中的应用', '刘慧慧,来壮壮,魏呵呵,王志强,胡培君', '摘要:ZnCr2O4(111)-OV表面作为CO选择性加氢反应的重要催化材料，其表面活性氢物种的产生机制及其对CO加氢反应的作用一直备受争议。本文研究了ZnCr2O4(111)-OV表面活性氢的产生及其在CO加氢中的应用，结果表明H2分子在ZnCr2O4(111)-OV表面异裂解离为OV-H−和O-H物种是最佳活化路径，这主要归因于ZnCr2O4(111)-OV表面Zn物种的灵活Zn3d轨道；其次，还发现OV-H−/O-H物种进攻CO分子的Cδ+/Oδ−时，动力学上更支持形成HCO物种而非COH物种；当以OH作为氢源进行CO选择性加氢反应时，H物种在反应过程中会优先转化为自由基；相反，若以OV-H−物种参与反应，其可直接作为氢源实现CO高选择性加氢。本文可为Zn-基合成气选择性加氢催化材料的理性设计提供潜在的理论指导。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240419001?viewType=HTML');
INSERT INTO `jou_info` VALUES (58, '掺杂元素对黄铜切削性能的影响', '顾宇,雷学林,沈宏涛,何云', '摘要:为探讨不同掺杂元素对黄铜合金切削性能的影响，制备了5种不同元素掺杂黄铜（2%（质量分数，下同）Sn黄铜、0.5%Sn黄铜、Sn-Fe黄铜、Pb黄铜、Si黄铜），并与H59黄铜的组织金相、力学性能、切削性能等进行对比。结果表明，2%Sn黄铜切削性能优于0.5%Sn黄铜；Sn-Fe黄铜和Pb黄铜因其晶界弥散着第二相颗粒质点，导致其切削和断屑性能较好。6种黄铜的切削力大小顺序为：0.5%Sn黄铜>2%Sn黄铜>Sn-Fe黄铜>Si黄铜>H59黄铜>Pb黄铜。Pb黄铜的切削性能较好但机械强度较差，Si黄铜具有不错的机械强度和切削性能。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240116002?viewType=HTML');
INSERT INTO `jou_info` VALUES (59, '超支化环氧树脂复合材料力学性能分子模拟', '王瑜,陈苏芳,张道洪,杨犁', '摘要:采用分子动力学（MD）模拟手段研究了双酚A二缩水甘油醚（DGEBA）支链分子和六氢均三嗪超支化环氧树脂（HHTE1）超支化分子作为改性剂的环氧树脂复合材料，预测了材料三维结构和支链的改变对力学性能的影响。结果表明，二维平面材料的弹性模量（E）、体积模量（K）、剪切模量（G）均大于一维线性结构材料的对应值（分别高出0.52%~1.61%、0.28%~1.04%、1.01%~2.89%）；三维立体结构较二维平面的E、K、G分别小于1.52%~3.33%、1.05%~4.35%、2.30%~3.13%。超支化分子HHTE1支链交联改性材料与DGEBA支链相比，其E、K、G均有明显提升（分别提升5.56%~11.9%，4.86%~10.86%、5.59%~10.74%）。本文构建的材料模型为晶体有序排列材料，研究其各向异性的力学性能发现，空间位阻与支链相互作用分别主导力学性能变化，其Ex、Ez、G(010)受支链作用和主链取向改变的影响，Ey、G(100)、G(001)受空间位阻作用。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240415001?viewType=HTML');
INSERT INTO `jou_info` VALUES (60, '液相除杂制备高纯硅酸钠溶液机理', '夏毅,吕慧,曹贵平', '摘要:硅酸钠溶液的纯度是影响液相法制备高纯二氧化硅的重要因素。本文提出以Ca2+作为硅酸钠溶液除杂剂，系统地研究除杂剂种类、反应时间、反应温度和nCa∶nSi对除杂效果的影响。硅酸钠溶液中按nCa∶nSi1∶20添加CaCl2试剂，在180℃下反应16h，溶液中Al、Fe和Ti杂质脱除率达到95%。分析除杂反应所得固体的晶体结构、表面形貌，表明在反应中Ca2+将溶液中的杂质离子以Ca-Si沉淀物的形式脱除，结合元素分布及元素质量占比分析结果，证明杂质离子成功结合到Ca-Si沉淀物中。通过分子模拟探究除杂反应的路径，模拟结果表明Ca-Si沉淀的形成由Ca2+和Si—O四面体形成的硅酸根结合，其中部分Si—O四面体中的Si被Al、Fe、Ti等金属杂质离子取代，形成含金属杂质的Ca沉淀物，因此沉淀中出现了Al、Fe、Ti等元素，Na和K等离子因电荷吸引而进入沉淀中，形成各类硅酸盐沉淀。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240207001?viewType=HTML');
INSERT INTO `jou_info` VALUES (61, '三瓣结构的滑梁式空气箔片轴承润滑力学建模及数值研究', '吴洋,韩怡萱,顾晨昀,冯伟军,安琦', '摘要:以三瓣结构的滑梁式空气箔片轴承为研究对象，基于最小位能原理和非线性薄板理论建立了箔片的刚度矩阵，并通过接触理论和牛顿法建立了箔片形变的计算模型；采用有限差分法计算等温雷诺方程，并通过流固耦合方法，建立了完整的滑梁式箔片轴承的力学模型。确定了计算流程，编写了计算程序，实现了对气膜压力分布、滑梁挠度和轴承极限载荷等参数的精确计算。结合具体算例，深入研究轴承参数对其性能的影响，研究表明，滑梁数目增多会降低轴承的最小气膜厚度，而增大轴向对称面的滑梁刚度可以提升轴承的极限承载能力。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240226003?viewType=HTML');
INSERT INTO `jou_info` VALUES (62, '磁性金属离子对羧甲基纤维素钠分散碳纳米管浆料性能的影响', '李博妍,公维光,景希玮,郑柏存', '摘要:多壁碳纳米管（MWNTs）制备过程中残留的磁性金属催化剂可能对其在溶剂中的分散产生影响。本文通过将MWNTs分别分散到含有同一浓度金属离子（Fe3+，Fe2+，Ni2+，Co2+）的羧甲基纤维素钠（CMC）溶液中，制备了一系列MWNTs浆料。并系统性地探究了浆料的吸附量、拉曼光谱、zeta电位和吸附构象。结果表明，CMC/MWNTs浆料的分散稳定性按照Fe2+、Co2+、Ni2+、Fe3+的顺序依次降低。CMC在MWNTs表面的吸附量与吸附构象受CMC与金属离子之间螯合反应的控制，这决定了CMC/MWNTs体系的分散和稳定性。含有二价离子的浆料中，CMC能够形成一层均匀的膜，覆盖在MWNTs表面，CMC吸附量最大，MWNTs表面zeta电位最大，表现出较好的分散稳定性。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20200614001?viewType=HTML');
INSERT INTO `jou_info` VALUES (63, '基于三维多孔填料的聚二甲基硅氧烷混合基质渗透汽化膜研究进展', '赵静,金万勤', '摘要:开发高性能渗透汽化膜材料是提高渗透汽化膜技术的竞争力，实现高效、低能耗有机溶剂分离回收过程的重要途径。聚二甲基硅氧烷（PDMS）是目前应用最为广泛的有机溶剂优先渗透型渗透汽化膜材料，但其分离性能不理想。在PDMS膜主体内引入多孔填料构筑混合基质膜，有望同时强化有机溶剂分子的溶解与扩散行为，实现分离性能的提升。与一维及二维填料相比，三维填料具有丰富连通的内部孔道，孔道结构一般不存在取向性，且填料种类及功能化手段丰富，是目前研究最为广泛的填料类型。本文综述了近年来基于三维多孔填料的PDMS混合基质膜的研究进展，分析了不同类型三维多孔填料的特点、混合基质膜的制备方法及影响其性能的关键因素，并提出了PDMS混合基质膜的研究挑战，以期为高性能PDMS混合基质膜的开发提供借鉴。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20240426001?viewType=HTML');
INSERT INTO `jou_info` VALUES (64, 'PBT推进剂中水氧扩散及键合作用的分子动力学模拟', '杨茜茜,王卫泽,杨敏,苏雅琪,轩福贞', '摘要:采用分子动力学模拟方法，对H2O和O2在三氟化硼三乙醇胺络合物（T313）中的扩散行为进行模拟，并研究了叠氮聚醚聚氨酯（PUPBT）/T313/高氯酸铵（AP）复合体系在不同界面层间的结合能和界面间的相互作用机理。扩散模拟结果显示，随着温度升高，H2O在T313中的扩散系数逐渐降低，O2在T313中的扩散系数逐渐增大，呈现出相反的变化趋势，表明极性分子和非极性分子在键合剂膜层中的扩散现象有显著差异。PUPBT加入键合剂T313后，与AP颗粒之间的结合将更加紧密。PUPBT/T313体系的界面黏附能力主要由PUPBT体系中的原子与T313中各原子之间的强范德华相互作用或氢键相互作用提供，而T313/AP体系的界面黏附能力主要由AP和PUPBT体系中原子之间的强范德华相互作用提供。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20231014001?viewType=HTML');
INSERT INTO `jou_info` VALUES (65, '电子级IPA微量金属离子吸附分离及其模拟', '张凯,陈寿天宝,许振良,程亮,陈亮,秦磊', '摘要:研究了树脂对异丙醇(IPA)中微量Na+和K+的静态吸附和动态吸附过程，其等温吸附符合Langmuir吸附模型，动力学吸附符合拟一级动力学模型。利用AspenAdsorption模拟了树脂对IPA中Na+和K+的动态吸附过程，模拟结果和实验测得的穿透曲线吻合良好。通过离子交换树脂去除IPA中的金属离子，最终金属离子质量浓度均低于5.00μg/L。这些结果为IPA中微量金属离子吸附装置的设计提供了依据。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20230910001?viewType=HTML');
INSERT INTO `jou_info` VALUES (66, '电子设备外壁自然散热综合传热系数仿真研究', '卢昕博,滕如玉,陈嘉彬,蒋健,韩玉峰,詹望成,周国俊,肖卫强', '摘要:采用Boussinesq假设对计算流体动力学中的自然对流传热行为进行研究，考察了电子设备外壁自然对流过程的传热特性。通过分析水平、竖直壁面和圆柱、球体曲面的自然对流过程，建立了自然对流传热系数公式。同时，研究了电子设备在工作环境下的辐射传热行为，简化了辐射传热方程，获得辐射传热系数公式。在此基础上，整合对流传热系数公式和辐射传热系数公式，获得和壁面温度相关的综合传热系数公式，该公式可以快速计算电子设备外壁与环境之间的传热量，为电子设备的热管理设计提供更为便捷和有效的研究手段。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20231115001?viewType=HTML');
INSERT INTO `jou_info` VALUES (67, '耦合有机朗肯循环的换热网络全局优化', '杨路,AKRAMNaeem,常承林,莫文龙,申威峰', '摘要:针对换热网络与有机朗肯循环耦合集成优化问题，建立了严谨的混合整数非线性规划（MINLP）模型。同时，通过添加与物流匹配的关键约束，剔除掉重复性的网络结构，开发了一种新型的枚举算法，将复杂的MINLP模型分解为混合整数线性规划（MILP）和非线性规划（NLP）两个子模型。迭代运行MILP模型，枚举出所有可行的网络结构；再利用全局求解器BARON优化每一个网络结构所对应的NLP模型，求得固定结构的年度总费用；最后对比所有网络结构的年度总费用，筛选出全局最优的设计方案。案例分析结果表明，该算法仅需16s就能收敛至全局最优解，与文献相比，年度总费用降低33.4%，且所提出的网络结构约束能使重复性的网络结构数量减少81.25%，从而提高算法的优化求解效率。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20231209002?viewType=HTML');
INSERT INTO `jou_info` VALUES (68, '基于AHP-EWM结合Box-Behnken响应面法优化黄芩多指标成分的微波提取工艺', '蒋佳丽,刘婷,李宇浩,韩伟,薛东升', '摘要:结合层次分析法（AHP）-熵权法（EWM），通过单因素实验考察功率、液固比、提取时间、提取次数和粒度对黄芩苷、汉黄芩苷、黄芩素和汉黄芩素得率及出膏率的影响。以综合评分为响应值，利用四因素三水平Box-Behnken（BBD）响应面法优化黄芩的微波提取工艺，并通过扫描电子显微镜（SEM）观察提取前后药材粉末的微观形态变化。BBD响应面法得到的最优提取工艺条件为：微波功率390W、液固比56mL/g、提取时间472s、粒度80目（180μm），此时黄芩苷、汉黄芩苷、黄芩素、汉黄芩素得率分别为16.82%、3.46%、0.30%、0.31%，出膏率73.73%，综合评分10.75。该工艺提取效果优于常见的回流提取方法，实现评价结果主客观的内在统一。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20230927001?viewType=HTML');
INSERT INTO `jou_info` VALUES (69, '提升头孢菌素C发酵效率的复合碳源补料工艺开发及代谢机制', '杨倚铭,陈震,田锡炜,储炬', '摘要:开发了一种以葡萄糖和豆油为底物碳源的复合补料策略，能够显著提升头孢菌素C（CPC）的合成效率，使其产量提升了14.8%，并观测到碳源变化在宏观呼吸代谢、中间代谢物、细胞内通量分配和还原力NADPH利用方面产生了全局影响，其中二氧化碳释放速率（CER）的变化表明在葡萄糖和豆油复合补料策略下细胞中心代谢网络的通量发生了明显改变，碳流向CPC的通量得到增强，同时促进了蛋氨酸和丝氨酸的胞外吸收。胞内有机酸α-酮戊二酸、丙酮酸、苹果酸的浓度明显提升，有利于谷氨酸、缬氨酸和半胱氨酸等核心氨基酸的合成，从而有利于CPC生产。主成分分析（PCA）的载荷测定结果表明大多数氨基酸和CPC合成呈正相关，谷氨酸的胞内含量与CPC合成的关联性最强，而α-氨基己二酸和赖氨酸积累反而不利于CPC合成。细胞还原力方面，豆油和葡萄糖组合工艺有助于NADPH更多地用于CPC合成，使得CPC快速合成时对NADPH的大量需求得到了满足。这些结果表明改变底物能够对细胞内部的代谢产生全方位的影响，复合补料策略在优化CPC合成中具有巨大潜力。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20230614001?viewType=HTML');
INSERT INTO `jou_info` VALUES (70, '基于红外视频的VOCs泄漏源定位与气羽实例分割', '江逸远,谷小婧,顾幸生', '摘要:为实现对基于红外视频的挥发性有机化合物（VOCs）的自动化检测，提出了一种泄漏源定位和气羽实例分割的协同建模方法，既保证了模型对气羽实例的区分，也保证了每个实例只预测一个泄漏源，并支持单支路网络通过单次前向推理同时进行泄漏源定位和实例分割。考虑到泄漏源附近的气羽逸散特性，使用泄漏源位置作为气羽在嵌入空间的聚类中心，并根据泄漏气羽的时空分布选取高斯分布概率密度函数的协方差变量，对嵌入空间内的像素进行聚类，得到不同实例的泄漏源定位和实例分割结果。将泄漏源定位问题定义为具有单一关键点的关键点检测问题并给出定量评价指标。此外，通过合成数据集获得更加精确且易于获取的标注。实验结果表明，本文提出的方法可以对泄漏气羽进行较为准确的泄漏源定位和实例分割，综合定量指标高于其他同类方法，且在真实视频中具有良好的泛化性。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20231011002?viewType=HTML');
INSERT INTO `jou_info` VALUES (71, '基于CVCS的浮法玻璃冷端机械手堆垛系统调度问题', '段雯娟,徐震浩,顾幸生', '摘要:采用目前生产线上常用的高速堆垛机（High-Speed-Stacker，HSS）和即时分拣机（Pick-on-the-Fly，POF）两种机械手分别堆垛不同规格的玻璃原片，目标是最小化玻璃的废料率。针对切割和抓取自动化过程，提出了一种组合Unit的方法最大化生产效率，并在此基础上采用了平衡Unit的优化方法。根据两种类型机械手是否同时工作，提出了混合抓取和分类抓取两种解决方案。最后针对抓取阶段的特点提出了一种组合变异布谷鸟搜索（CombinationVariationCuckooSearch，CVCS）算法，引入了内外逆序和多领域插入变异操作，防止算法陷入局部最优。仿真实验采用响应面分析法对CVCS进行参数标定。并将CVCS与MMGA、BPSO、DABC、CS算法进行了对比分析，实验结果验证了CVCS算法解决该问题的优越性。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20230719001?viewType=HTML');
INSERT INTO `jou_info` VALUES (72, '一种基于冷扩散模型的复杂反应流场建模方法', '陈俊宏,程辉,胡贵华', '摘要:仿真复杂湍流反应流场的计算消耗巨大，为了缓解计算负担，许多研究基于深度学习方法构建数据驱动代理模型，但获取该代理模型所需要的数据仍存在一定困难。为了解决上述问题，本文提出一种基于冷扩散模型（ColdDiffusionModel，CDM）的代理模型。与去噪扩散概率模型（DenoisingDiffusionProbabilisticModel，DDPM）不同，插值冷扩散模型在扩散过程中采用逐步插值替代加入随机高斯噪声，为复原过程引入更多信息。二维甲烷燃烧仿真实验结果表明，相比其他代理模型，插值冷扩散模型能够利用有限的数据，学习到更多的信息，减少训练所需的计算数据量，从而缓解计算负担。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20231010001?viewType=HTML');
INSERT INTO `jou_info` VALUES (73, '基于深度学习的农场虫情检测算法研究及实现', '罗小娟,胡鹏昊', '摘要:传统的病虫害防治手段需要消耗大量人力、物力，且达不到很高的精确度，为了更科学、高效地做好农场病虫害防治工作，本文结合深度学习技术和物联网技术研发了虫情检测系统进行病虫害的远程检测，提高防治工作的效率。该系统采用YOLO-v5网络模型，结合迁移学习，训练学习了林业常见害虫和农田常见害虫的特征，实现了高效的检测识别。基于物联网技术实现远程控制拍摄病虫害图像，并通过Wi-Fi传输到计算机端进行识别，通过可视化界面呈现出农田中虫害的种类和数量，对减少人力、物力消耗以及实现科学防虫具有良好的实际应用价值。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20231007001?viewType=HTML');
INSERT INTO `jou_info` VALUES (74, '基于子空间字典低秩表示的流形投影学习', '冯文熠,王喆', '摘要:低秩表示(Low-RankRepresentation，LRR)能够将每个数据点表示为若干个基的线性组合，是一种获取样本底层低维结构的方法。然而，大多数LRR方法使用原始数据集作为字典，这不能揭示数据的真实分割。本文提出了基于子空间字典低秩表示的流形投影学习：该方法学习最优子空间作为LRR问题的字典，而不是使用原始数据集；利用基数最少的方案，低秩表示矩阵能很好地恢复原始数据；通过对投影矩阵施加行稀疏约束，该方法不仅可以选择鉴别性特征并忽略冗余特征，而且使子空间学习具有很好的解释性。此外，通过引入流形结构保持约束，使得样本的原始表示和距离信息在投影下保持不变。在多个真实世界数据集上的实验结果表明，该方法优于最近提出的一些相关方法。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20231013002?viewType=HTML');
INSERT INTO `jou_info` VALUES (75, '基于深度学习的人体姿态估计与追踪', '张雪芹,朱荟潼,王宁', '摘要:随着深度学习技术的发展，基于卷积神经网络的人体姿态估计和追踪的准确率得到大幅提高。但在面对遮挡问题时，还存在人体关键点检测困难、姿态追踪精度偏低和速度较慢等问题。本文针对这些问题，构建了一个ybasTrack多人姿态估计和追踪模型；提出采用一种改进的YOLOv5s网络进行目标检测；采用BCNet分割网络区分遮挡与被遮挡人体，限定人体关键点定位区域；基于Alphapose的SPPE（Single-PersonPoseEstimator）进行改进，优化人体关键点检测结果；采用改进的Y-SeqNet网络进行行人重识别，采用MSIM（Multi-PhaseIdentityMatching）身份特征匹配算法对人体框、人体姿态和人体身份信息进行匹配，实现人体姿态追踪。实验表明，所提算法对遮挡场景下的人体姿态估计和姿态追踪具有较好的效果，模型运行具有较快速度。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20231018001?viewType=HTML');
INSERT INTO `jou_info` VALUES (76, '基于PSO-LSTM模型的上肢动作识别方法', '常钰坤,曹港生,马振九,康高峰,夏春明', '摘要:针对上肢肌音信号(Mechanomyography，MMG)动作识别准确率不高的问题，提出一种基于粒子群算法(PSO)与长短期记忆网络相结合的混合模型(ParticleSwarmOptimization-LongShortTermMemory，PSO-LSTM)的动作识别方法。采用5通道传感器对受试者进行上肢肌音信号采集，使用巴特沃斯滤波(ButterworthFilter)等方法对肌音信号进行预处理，并进行特征提取；构建基于PSO-LSTM的上肢肌音信号识别模型并进行模型训练和测试；最后从不同测度对比了长短期记忆(LSTM)模型、麻雀搜索算法(SparrowSearchAlgorithm，SSA)优化的LSTM模型(SparrowSearchAlgorithm-LongShortTermMemory,SSA-LSTM)以及PSO-LSTM模型的实验结果。结果表明，PSO-LSTM模型的准确度均高于LSTM、SSA-LSTM模型，达到96.9%左右，在迭代损失、迭代速度等方面也优于LSTM、SSA-LSTM模型，从而证明了该模型用于上肢肌音信号识别的优越性。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20231009001?viewType=HTML');
INSERT INTO `jou_info` VALUES (77, '基于BP神经网络的Smith-Fuzzy-PID算法在阀门定位中的应用研究', '谢涛,周邵萍,王佳硕,裴梓敬', '摘要:为解决气动调节阀控制过程中出现的超调大、精度低等问题，本文采用BP神经网络整定出较优的PID（ProportionalIntegralDerivative）控制参数，对Smith预估控制器以及模糊控制器进行设计，实现了基于BP神经网络的Smith-Fuzzy-PID控制方法。搭建了实验平台，通过阶跃响应实验来对控制方法进行验证，验证结果表明，提出的方法调节过程无超调，调节时间仅为1.9s，定位精度在±0.5%以内，有效提高了系统的稳定性，实现了气动调节阀的快速精准定位。', 'https://journal.ecust.edu.cn/article/doi/10.14135/j.cnki.1006-3080.20230830001?viewType=HTML');
